"""The baseline in `AGENTS.md` and the Claude Code bridge (proposal section 12.4)."""

from __future__ import annotations

from orqlet.adapters.render.emit import normalise_text
from orqlet.application.ports.instruction_adapter import RenderedFile, RenderRequest
from orqlet.domain.blocks import render_block
from orqlet.domain.digest import sha256_hex
from orqlet.domain.ownership import FileClass, OwnerMode
from orqlet.domain.paths import CanonicalPath

GENERATED_NOTICE = (
    "<!-- Generated by Orqlet. Do not edit by hand; see .orqlet/generated.lock.yaml. -->"
)
BASELINE_BLOCK = "baseline"
AGENTS_PATH = CanonicalPath.parse("AGENTS.md")
BRIDGE_PATH = CanonicalPath.parse(".claude/CLAUDE.md")


def agents_block(request: RenderRequest) -> RenderedFile:
    """The baseline as a managed block of `AGENTS.md`, which Codex and Cursor read natively."""
    body = normalise_text(request.baseline_body).rstrip("\n")
    digest = sha256_hex(body.encode("utf-8"))
    info = f"workflow@{request.workflow_version}#{digest}"
    block = render_block(BASELINE_BLOCK, info, body)
    begin, end = block.rstrip("\n").split("\n")[0], block.rstrip("\n").split("\n")[-1]
    return RenderedFile(
        path=AGENTS_PATH,
        content=block.encode("utf-8"),
        owner=OwnerMode.SHARED_BLOCK,
        file_class=FileClass.PROTECTED,
        inputs=((BASELINE_BLOCK, request.workflow_version, digest),),
        block=(begin, end),
    )


def claude_bridge() -> RenderedFile:
    """`.claude/CLAUDE.md`: Claude Code reads it as the project's instructions.

    It follows the import to `AGENTS.md`. The path climbs out of `.claude/` because imports
    resolve relative to the file that holds them.
    """
    text = f"{GENERATED_NOTICE}\n@../AGENTS.md\n"
    return RenderedFile(
        path=BRIDGE_PATH,
        content=text.encode("utf-8"),
        owner=OwnerMode.ORQLET,
        file_class=FileClass.PROTECTED,
        inputs=(("claude-bridge", "1", sha256_hex(text.encode("utf-8"))),),
    )


def claude_import_block(*, import_path: str) -> str:
    """The block that adds the import to a `CLAUDE.md` the project already owns.

    `import_path` is `@AGENTS.md` for a root-level file and `@../AGENTS.md` inside `.claude/`.
    """
    if import_path not in {"@AGENTS.md", "@../AGENTS.md"}:
        raise ValueError(f"not an import Orqlet writes: {import_path!r}")
    return render_block("claude-import", "", import_path)
